const wogTotalForYear = `-- name: WogTotalForYear :one
SELECT w.amount, w.estimate_type, sd.title
FROM wog_expense w
JOIN source_document sd ON sd.id = w.source_document_id
WHERE sd.budget_year = ? AND w.fiscal_year = ? AND w.lens = 'function' AND w.category = 'Total expenses'
`

type WogTotalForYearParams struct {
	BudgetYear string
	FiscalYear string
}

type WogTotalForYearRow struct {
	Amount       int64
	EstimateType string
	Title        string
}

// The published total expenses from the BP1 of the same budget year.
func (q *Queries) WogTotalForYear(ctx context.Context, arg WogTotalForYearParams) (WogTotalForYearRow, error) {
	row := q.db.QueryRowContext(ctx, wogTotalForYear, arg.BudgetYear, arg.FiscalYear)
	var i WogTotalForYearRow
	err := row.Scan(&i.Amount, &i.EstimateType, &i.Title)
	return i, err
}
